def main():
    bank=read(P/'e0_reference/ADMISSION_BANK.json')
    sk={x['qid']:x for x in read(P/'e0_reference/QUESTION_SKELETONS.json')}
    refs=[]
    for r in bank:
        rid,atoms,forbidden=DATA[r['source_id']]
        requirement=next(x for x in sk[r['qid']]['R'] if x['requirement_id']==rid)
        aa=[]
        for i,(statement,anchor) in enumerate(atoms):
            assert anchor in r['source_observation']['text'],(r['source_id'],anchor)
            aa.append({'atom_id':f"{r['source_id']}_F{i+1}",'semantic_content':statement,'source_anchor':anchor,
                       'source_anchor_start':r['source_observation']['text'].index(anchor),
                       'anchor_is_locator_not_necessarily_complete_proof':True})
        refs.append({'source_id':r['source_id'],'observation_id':r['observation_id'],'qid':r['qid'],
                     'relevant_requirement':requirement,'acceptable_claim_atoms':aa,
                     'forbidden_upgrades':forbidden,'observation_sha256':r['observation_sha256'],
                     'zero_recall_atoms_means':'no predesignated useful facts; other safe entailed outputs are not automatically false admissions',
                     'source_fidelity_only':True})
    assert len(DATA)==len(refs)==53
    write(P/'e0_reference/ADMISSION_REFERENCE.json',refs)
    write(P/'e0_reference/REFERENCE_COUNTS.json',{'observations':53,'qids':20,
          'acceptable_atoms':sum(len(r['acceptable_claim_atoms']) for r in refs),
          'observations_without_required_atoms':sum(not r['acceptable_claim_atoms'] for r in refs),
          'reviewer':'single task-familiar Codex; source-only pre-call review; no independent-review claim',
          'references_frozen_before_new_model_calls':True})
    print('Gold atoms',sum(len(r['acceptable_claim_atoms']) for r in refs))

if __name__=='__main__':main()
